import json
import uuid

from requests import HTTPError, Session
from taf.internal.impact_radar import log_radar

from .exceptions import AuthenticationFailed


class PmRestApi:
    KPIS_TYPE = ['all', 'system', 'custom']

    def __init__(self, web_url, username, password):
        self.web_url = web_url
        self.username = username
        self.password = password
        self._session = Session()
        self._session.verify = False

    def _request(self, method, url, **kwargs):
        log_radar(
            "Sending NetAct request",
            request_method=method,
            request_url=url,
            request_params=kwargs.get("params"),
            request_data=json.dumps(kwargs.get("json")),
        )
        response = self.session.request(method, url, **kwargs)
        if response.history and response.url.endswith('sessiontimeout.html'):
            self._session.cookies.clear_session_cookies()
            response = self.session.request(method, url, **kwargs)
        if response.status_code == 400:
            resp_json = response.json()
            exc_msg = (
                f"400 Client Error: {resp_json['errorTitle']} for url: {response.url}\n"
                f"Error code: {resp_json['errorCode']}, root cause: {resp_json['userMessage']}"
            )
            raise HTTPError(exc_msg)
        response.raise_for_status()
        return response.json()

    def _remove_links(self, input_list, nested_keys=None):
        nested_keys = nested_keys or []
        for item in input_list:
            if 'links' in item:
                del item['links']
            for key in nested_keys:
                if key in item:
                    item[key] = self._remove_links(item[key], nested_keys)
        return input_list

    def _get(self, url, params=None):
        response = self._request(method='GET', url=url, params=params)
        return response['content']

    def _post(self, url, json=None):
        response = self._request(method='POST', url=url, json=json)
        return response['data']

    def _build_url(self, endpoint):
        return f'https://{self.web_url}{endpoint}'

    @property
    def session(self):
        if not self.authenticated:
            self._authenticate()
        return self._session

    @property
    def authenticated(self):
        return 'LtpaToken2' in self._session.cookies

    def _authenticate(self):
        endpoint = '/pmservices/j_security_check'
        url = self._build_url(endpoint)
        data = {
            'j_username': self.username,
            'j_password': self.password
        }
        self._session.post(url=url, data=data)
        if not self.authenticated:
            raise AuthenticationFailed('Invalid username or password.')

    def get_adaptations(self):
        """
        Retrieve list of all adaptations

        Example output::

            [
                {
                    'content':
                        {
                            'counters': True,
                            'customKPIs': False,
                            'sharedKPIs': False,
                            'systemKPIs': False
                        },
                    'description': 'LNBTS-NSN LTE Base Transceiver Station',
                    'id': 'NOKLTE',
                    'modificationTime': '2024-04-11T15:23:13+03:00',
                    'releaseId': 'rslte'
                },
                {
                    'content':
                        {
                            'counters': True,
                            'customKPIs': False,
                            'sharedKPIs': False,
                            'systemKPIs': False
                        },
                    'description': 'NRBTS-Nokia AirScale BTS 5G',
                    'id': 'NOKGNB',
                    'modificationTime': '2024-04-12T13:42:52+03:00',
                    'releaseId': 'nokgnb'
                }, ...
            ]

        :return: AdaptationDtoCollection
        :rtype: list(dict)
        """
        endpoint = '/pmservices/api/v1/adaptations'
        url = self._build_url(endpoint)
        response = self._get(url=url)
        return self._remove_links(response, ['contentReleases'])

    def get_kpis(self, adaptation_id, release_id=None, kpis_type=None, shared=None):
        """
        Retrieve installed KPIs for a specific adaptation.

        Example output::

            [
                {
                    'adaptation': 'NOKLTE',
                    'alias': 'period_duration',
                    'deprecated': False,
                    'id': 'Alarms_period_duration',
                    'name': 'period_duration',
                    'permissions': ['GET'],
                    'reference': 'rslte_24R2:kpis:Alarms_period_duration#Alarms_period_duration',
                    'release': 'rslte_24R2',
                    'shared': True,
                    'unit': 'min'
                },
                {
                    'adaptation': 'NOKLTE',
                    'alias': 'Intra eNB HO PREP FR due Other',
                    'deprecated': False,
                    'id': 'LTE_39a',
                    'name': 'Intra eNB Handover Preparation Failure Ratio due Other',
                    'permissions': ['GET'],
                    'reference': 'rslte_24R2:kpis:LTE_39a#LTE_39a',
                    'release': 'rslte_24R2',
                    'shared': True,
                    'unit': '%'
                }, ...
            ]

        :param string adaptation_id: Technology adaptation id, e.g., `NOKLTE`.
        :param string release_id: Technology release id, e.g, `rslte`.
        :param string kpis_type: The type of KPIs. Allowed values: ''all'', ''custom'' and ''system''.
        :param bool shared: Specifies if shared KPIs should be taken into account.
        :return: KPIDto
        :rtype: list(dict)
        """
        endpoint = f'/pmservices/api/v1/adaptations/{adaptation_id}/kpis'
        url = self._build_url(endpoint)
        kpis_type = kpis_type.lower()
        if kpis_type not in self.KPIS_TYPE:
            exc_msg = (f"{kpis_type!r} value is not a valid kpis_type. "
                       f"Must be one of: {', '.join(self.KPIS_TYPE)}")
            raise ValueError(exc_msg)
        params = {
            'release': release_id,
            'type': kpis_type,
            'shared': shared
        }
        response = self._get(url=url, params=params)
        return self._remove_links(response)

